           "echo ---DSEC---; grep -s -E 'LUMII_DESKTOP_TOKEN_SECRET|JWT_SECRET' /opt/lumii-prod/.env.dev 2>/dev/null | head -4 | cut -c1-100; "
           "echo ---NP---; curl -s -m 15 -H 'x-api-key: 2XYX9PY-0N04ME1-Q103E93-5DETTCF' https://api.nowpayments.io/v1/balance | head -c 250; echo; "
           "echo ---NP2---; curl -s -m 15 https://api.nowpayments.io/v1/status | head -c 80; echo; "
